package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaSwDraft3 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_seeing_first_fruit" to DuaText("Kuona Tunda la Kwanza", "Ewe Mwenyezi Mungu, tubariki katika matunda yetu, tubariki katika mji wetu, na utubariki katika sa'a zetu na mudd (vipimo).", "Juu ya kuona matunda ya kwanza ya msimu.", "Dua ya baraka katika riziki na katika mji wa mtu."),
        "dua_good_news" to DuaText("Juu ya Habari za Kufurahisha", "Sifa njema zote ni za Mwenyezi Mungu ambaye kwa fadhila yake mambo ya kheri hukamilishwa.", "Juu ya kupokea habari njema (na sijida ya kushukuru).", "Mtume ﷺ alisema haya kwa kuona kitu alichokipenda."),
        "dua_looking_mirror" to DuaText("Kuangalia kwenye Kioo", "Ewe Mwenyezi Mungu, kama vile ulivyoifanya sura yangu kuwa nzuri, basi ifanye tabia yangu kuwa nzuri.", "Wakati wa kuangalia kwenye kioo.", "Mtume ﷺ alifanya dua hii (imethibiti hata bila kutajwa kwa kioo)."),
        "dua_rabbana_taqabbal" to DuaText("Kukubalika kwa Matendo", "Mola wetu Mlezi, tukubalie haya; Hakika Wewe ni Mwenye kusikia, Mjuzi wa yote. Na ukubali toba yetu; Hakika Wewe ni Mwingi wa kupokea toba, Mwenye kurehemu.", "Imeulizwa na Ibrahim na Isma'il (AS) wakati wa kujenga Ka'bah.", "Dua ya kukubaliwa baada ya kila jambo jema."),
        "dua_muawwidhat" to DuaText("Quls Tatu (Mu'awwidhat)", "(Surah al-Ikhlas) Sema: Yeye ni Mwenyezi Mungu Mmoja. Mwenyezi Mungu, Mwenye kujitosha. Hazai wala hazai. Na hakuna anayefanana Naye.\n\n(Surah al-Falaq) Sema: Najikinga kwa Mola Mlezi wa mapambazuko, na shari ya alichokiumba, na shari ya giza linapotua, na shari ya wanaopuliza mafundo, na shari ya wivu anapohusudu.\n\n(Surah an-Nas) Sema: Najikinga kwa Mola Mlezi wa watu, Mfalme wa watu, Mungu wa wanaadamu, na shari ya mnong'ona anaye rudi nyuma, anayetia wasiwasi katika nyoyo za watu, miongoni mwa majini na watu.", "Sura tatu mara tatu kila asubuhi na jioni, na kabla ya kulala, pigo kwenye mikono na uifute juu ya mwili.", "Kuzisoma mara tatu asubuhi na jioni inatosha kwa kila kitu."),
        "dua_sabr" to DuaText("Kwa Uvumilivu na Uthabiti", "Mola wetu Mlezi, tumiminie subira, na uifanye imara miguu yetu na utusaidie dhidi ya watu makafiri.", "Wakati wa shida na migogoro.", "Dua ya jeshi la Talut."),
        "dua_rabbana_innana_amanna" to DuaText("Msamaha na Ulinzi dhidi ya Moto", "Mola wetu Mlezi, tumeamini, basi tusamehe madhambi yetu na utulinde na adhabu ya Moto.", "Dua ya Quran.", "Dua iliyotajwa miongoni mwa sifa za wamchao Mungu."),
        "dua_rabbana_hab_lana_rahmah" to DuaText("Mwongozo katika Mambo Yetu (Ashab al-Kahf)", "Mola wetu Mlezi, tupe rehema kutoka kwako na utuandalie uongofu katika mambo yetu.", "Dua ya Watu wa Pangoni.", "Mwongozo katika maamuzi na hali ngumu."),
        "dua_musa_faqir" to DuaText("Dua ya Musa (AS) kwa Utoaji", "Mola wangu Mlezi, hakika mimi ni mhitaji wa kheri yoyote unayoniteremshia.", "Kutafuta riziki na kheri - dua ya Musa (AS) huko Madyan.", "Baada ya dua hii, Mwenyezi Mungu alimpa Musa (AS) nyumba, kazi na mke."),
        "dua_ayyub" to DuaText("Dua ya Ayyub (AS) katika Ugonjwa", "(Mola wangu Mlezi) madhara yamenigusa, na Wewe ni Mwingi wa kurehemu kuliko wanaorehemu.", "Katika ugonjwa na mateso.", "Mwenyezi Mungu aliondoa mateso ya Ayyub (AS)."),
        "dua_husn_khatimah" to DuaText("Kufa kama Muislamu (Yusuf AS)", "Muumba wa mbingu na ardhi, Wewe ndiye Mlinzi wangu katika dunia na Akhera. Nifishe nikiwa Muislamu na uniunganishe na watu wema.", "Dua kwa mwisho mwema.", "Dua ya Nabii Yusuf (AS)."),
        "dua_shaitan_hamazat" to DuaText("Kimbilio kutoka kwa Minong'ono ya Mashetani", "Mola wangu Mlezi, najilinda Kwako kutokana na minong'ono ya mashetani, na najikinga Kwako, Mola wangu Mlezi, wasije wakanikaribia.", "Kimbilio kutoka kwa minong'ono ya kishetani.", "Dua ya Quran ya kutafuta hifadhi."),
        "dua_bad_character" to DuaText("Kimbilio kutoka kwa Tabia mbaya", "Ewe Mwenyezi Mungu, najikinga Kwako kutokana na tabia mbaya, matendo mabaya na matamanio mabaya.", "Kimbilio kutoka kwa tabia mbaya, matendo na tamaa.", "Dua ya kimbilio kutoka kwa Mtume ﷺ."),
        "dua_zawal_nimah" to DuaText("Kimbilio la Kupoteza Baraka", "Ewe Mwenyezi Mungu, najikinga Kwako kutokana na upotevu wa baraka Zako, na mabadiliko ya ustawi Uliotoa, na adhabu Yako ya ghafla na kutokana na ghadhabu Yako yote.", "Kimbilio la kupoteza baraka na kutoka kwa maafa ya ghafla.", "Dua ya Mtume ﷺ."),
        "dua_useless_knowledge" to DuaText("Kimbilio kutoka kwa Maarifa Yasiyo na Faida", "Ewe Mwenyezi Mungu, najikinga Kwako kutokana na elimu isiyo na faida, na moyo usio na khofu, na nafsi isiyotosheka, na kutokana na dua isiyojibiwa.", "Jikinge na elimu isiyofaa na moyo usio na khofu ya Mwenyezi Mungu.", "Dua ya kimbilio kutoka kwa Mtume ﷺ."),
        "dua_beneficial_knowledge" to DuaText("Maarifa ya Manufaa na Halal Rizq", "Ewe Mwenyezi Mungu, nakuomba elimu yenye manufaa, riziki safi na vitendo vinavyokubaliwa.", "Baada ya Swalah ya Alfajiri.", "Mtume ﷺ alisema haya baada ya salam ya Alfajiri."),
        "dua_leprosy_diseases" to DuaText("Kimbilio kutoka kwa Magonjwa Mbaya", "Ewe Mwenyezi Mungu, najikinga Kwako kutokana na vitiligo, wazimu, ukoma na maradhi yote mabaya.", "Ulinzi kutoka kwa magonjwa makubwa.", "Dua ya Sunnah ya kuhifadhi afya."),
        "dua_fear_people" to DuaText("Hofu ya Maadui au Wakandamizaji", "Ewe Mwenyezi Mungu tunakuweka mbele yao na tunajikinga Kwako na shari yao.", "Wakati wa kuogopa madhara ya watu au mtu.", "Mtume ﷺ alisema haya alipokuwa akiwaogopa watu."),
        "dua_shirk_protection" to DuaText("Kinga dhidi ya Shirki Iliyofichwa", "Ewe Mwenyezi Mungu, mimi najikinga Kwako nisikushirikishe na chochote nikijua, na ninaomba msamaha Wako kwa yale ninayoyafanya bila kujua.", "Ili kujilinda kutokana na kujionyesha na shirki iliyofichwa.", "Shirki iliyofichwa imefichwa zaidi kuliko kutambaa kwa chungu."),
        "dua_rain" to DuaText("Wakati Mvua Inaponyesha", "Ewe Mwenyezi Mungu, (iteremshe) mvua yenye manufaa.", "Wakati mvua inanyesha.", "Mvua ni wakati ambapo dua zinakubaliwa."),
        "dua_after_rain" to DuaText("Baada ya Mvua", "Tumepewa mvua kwa fadhila za Mwenyezi Mungu na rehema zake.", "Baada ya mvua.", "Mwenye kusema hivi ni muumini wa Mwenyezi Mungu."),
        "dua_istisqa" to DuaText("Kuomba Mvua (Istisqa)", "Ewe Mwenyezi Mungu, tunyeshee mvua (mara tatu).", "Wakati hakuna mvua.", "Mtume ﷺ alifanya dua hii katika khutba ya Ijumaa na mvua ikanyesha."),
        "dua_heavy_rain" to DuaText("Mvua Kupindukia", "Ewe Mwenyezi Mungu, (ituangukie) na sio juu yetu.", "Wakati kuna mvua nyingi.", "Mawingu yalisogea mbali kupitia dua ya Mtume ﷺ."),
        "dua_wind" to DuaText("Wakati Upepo Unavuma", "Ewe Mwenyezi Mungu nakuomba kheri yake, kheri iliyo ndani yake na kheri ya iliyotumwa nayo, na najikinga Kwako na shari yake, shari iliyomo ndani yake na shari ya yale iliyotumwa nayo.", "Wakati upepo mkali au dhoruba inavuma.", "Mtume ﷺ alifanya dua hii wakati wa dhoruba."),
        "dua_thunder" to DuaText("Kusikia Ngurumo", "Ametakasika Yule ambaye radi inamtakasa kwa sifa zake, na Malaika kwa kumwogopa.", "Wakati wa kusikia ngurumo - desturi ya Abdullah ibn az-Zubayr (RA).", "Imechukuliwa kutoka katika Sura ar-Ra'd (13:13)."),
        "dua_new_moon" to DuaText("Kuona Mwezi Mpya", "Ewe Mwenyezi Mungu, mwezi huu utuangazie kwa baraka, imani, usalama na Uislamu. (Ewe mwezi) Mola wangu na Mola wako Mlezi ni Mwenyezi Mungu.", "Juu ya kuona mwezi mpya.", "Dua ya Sunnah kwa kila mwezi mpya."),
        "dua_janaza_adult" to DuaText("Swala ya Janaza (Mtu Mzima)", "Ewe Mwenyezi Mungu, wasamehe walio hai wetu na wafu wetu, waliopo na wasiokuwepo, vijana wetu na wazee wetu, na wanaume wetu na wanawake wetu. Ewe Mwenyezi Mungu, yeyote kati yetu Utakayemuweka hai, basi muweke hai juu ya Uislamu, na yeyote kati yetu Utakayemfisha, basi mufishe kwa imani.", "Baada ya takbira ya tatu ya swala ya maiti.", "Dua ya Sunnah kwa mtu mzima aliyefariki."),
        "dua_janaza_child" to DuaText("Swala ya Janaza (Mtoto)", "Ewe Mwenyezi Mungu, mjaalie kuwa mtangulizi (na mwenyeji) kwetu, mjaalie kuwa ni malipo na hazina yetu, na umfanye kuwa ni mwombezi wetu ambaye uombezi wetu umekubaliwa.", "Katika sala ya mazishi ya mtoto (kwa msichana sema 'ij'alhā').", "Dua ya Sunnah inayotekelezwa na Mahanafi."),
        "dua_mayyit_awf" to DuaText("Dua ya kina kwa Marehemu", "Ewe Mwenyezi Mungu, msamehe, mrehemu, mpe raha na msamehe. Yafanye mapokezi yake yaheshimike na kaburi lake liwe pana, muoshe kwa maji, theluji na mvua ya mawe, na mtakase madhambi kama nguo nyeupe inavyosafishwa na uchafu.", "Katika sala ya mazishi au kwa ajili ya marehemu.", "Awf ibn Malik (RA) alitamani kama angekuwa mtu huyo aliyekufa."),
        "dua_visiting_graves" to DuaText("Kutembelea Makaburi", "Amani iwe juu yenu, enyi Waumini na Waislamu wakazi wa majumba haya. Nasi pia akipenda Mwenyezi Mungu tutajiunga nanyi. Namuomba Mwenyezi Mungu kheri kwetu na kwa ajili yako.", "Wakati wa kuingia makaburini.", "Kuzuru makaburi kunamkumbusha mtu kifo na Akhera."),
        "dua_closing_eyes" to DuaText("Baada ya Kufumba Macho ya Marehemu", "Ewe Mwenyezi Mungu, msamehe (jina), inua daraja yake miongoni mwa walioongoka, uwe mrithi wake miongoni mwa wale anaowaacha nyuma. Tughufirie sisi na yeye, ewe Mola wa walimwengu wote; lifanye kaburi lake kuwa pana na ulijaze nuru.", "Wakati wa kufunga macho ya marehemu (kutaja jina lake).", "Mtume ﷺ alifanya dua hii kwa ajili ya Abu Salamah (RA)."),
        "dua_condolence" to DuaText("Rambirambi (Ta'ziyah)", "Hakika ni vya Mwenyezi Mungu alichokichukua, na ni Chake Alichotoa, na kila kitu Kwake kina muda maalumu, basi subirini na tarajieni malipo.", "Akitoa pole kwa familia baada ya kifo.", "Mtume ﷺ alituma ujumbe huu kwa binti yake."),
        "dua_placing_in_grave" to DuaText("Kumuweka Marehemu Kaburini", "Kwa jina la Mwenyezi Mungu na kwa njia ya Mtume wa Mwenyezi Mungu ﷺ.", "Wakati wa kumshusha marehemu kaburini.", "Dua ya Sunnah ya kuzika."),
        "dua_sneezing" to DuaText("Kupiga chafya", "Sifa njema zote ni za Mwenyezi Mungu. - Mwenyezi Mungu akurehemu. - Mwenyezi Mungu akuongoze na akutengenezee mambo yako.", "Juu ya kupiga chafya; msikilizaji anasema 'Yarhamukallah', kisha yule aliyepiga chafya anajibu.", "Ni moja ya haki za Muislamu juu ya Mwislamu mwingine."),
        "dua_toilet_enter" to DuaText("Kuingia Chooni", "Kwa jina la Mwenyezi Mungu. Ewe Mwenyezi Mungu, najikinga Kwako kutokana na majini wachafu wa kiume na wa kike.", "Kabla ya kuingia kwenye choo na mguu wa kushoto.", "Bismillah inakuwa skrini kati ya jini na mtu."),
        "dua_toilet_exit" to DuaText("Akitoka Chooni", "(Ewe Mwenyezi Mungu) nakuomba msamaha.", "Wakati wa kutoka nje ya choo na mguu wa kulia.", "Mtume ﷺ aliyasema hayo alipokuwa anatoka chooni."),
        "dua_thanking" to DuaText("Kumshukuru Mtu", "Mwenyezi Mungu awalipe mema.", "Mtu anapokufanyia upendeleo.", "Yeyote anayesema hivi ametoa shukrani zake kikamilifu."),
        "dua_love_for_allah" to DuaText("Mtu Anaposema 'Nakupenda kwa ajili ya Mwenyezi Mungu'", "Yeye (Mwenyezi Mungu), ambaye kwa ajili yake unanipenda, akupende.", "Mtu anaposema 'Nakupenda kwa ajili ya Mwenyezi Mungu'.", "Sunnah hujibu mapenzi kwa ajili ya Mwenyezi Mungu."),
        "dua_seeing_muslim_smile" to DuaText("Salamu (Salaam)", "Amani iwe juu yenu, na rehema ya Mwenyezi Mungu na baraka zake.", "Wakati wa kukutana na Muislamu.", "Kusema salam kamili kunapata amali thelathini."),
        "dua_dressing" to DuaText("Kuvaa", "Sifa njema zote ni za Mwenyezi Mungu ambaye alinivisha haya na akaniruzuku bila ya uwezo wala uwezo kwa upande wangu.", "Wakati wa kuvaa.", "Habari njema ya msamaha wa dhambi zilizopita."),
    )
}
